"use client";

/**
 * Model QA: every model output for a garment, next to the image it came from.
 *
 * The point of this page is to make "is the model any good" answerable by
 * LOOKING. Querying Postgres answers it too, but not while you are holding the
 * photo in your head, which is when the judgement is actually reliable.
 *
 * Its most important job is refusing to flatter the model. Three different
 * things in this database look like tags and only one is a prediction:
 * real model output, a deterministic mock that answers "kurta" for
 * everything, and rows generated by the seed script. A grid that renders all
 * three identically would make the model look confident and competent when it
 * has not run at all — so provenance is stated per garment and once, loudly,
 * at the top.
 */

import Link from "next/link";
import { useCallback, useEffect, useState } from "react";
import { type EvalItem, type EvalPage, evalView, getToken } from "@/lib/api";

const PAGE = 12;

function Confidence({ f }: { f: EvalItem["fields"][number] }) {
  if (f.user_verified) {
    // Ground truth, not a prediction. Counting it as a model success would
    // inflate accuracy with the user's own corrections.
    return <span className="tag verified">you set this</span>;
  }
  if (f.confidence === null) return <span className="tag none">no score</span>;
  const pct = (f.confidence * 100).toFixed(0);
  return (
    <span className={`tag ${f.below_threshold ? "low" : "ok"}`}>
      {pct}%
      {f.review_below !== null && f.below_threshold && (
        <span className="thr"> &lt; {(f.review_below * 100).toFixed(0)}%</span>
      )}
    </span>
  );
}

export default function EvalPageView() {
  const [page, setPage] = useState<EvalPage | null>(null);
  const [offset, setOffset] = useState(0);
  const [onlyReal, setOnlyReal] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [showOriginal, setShowOriginal] = useState<Record<string, boolean>>({});

  const load = useCallback(async () => {
    try {
      setPage(await evalView({ limit: PAGE, offset, onlyReal }));
      setError(null);
    } catch (e) {
      setError(String(e));
    }
  }, [offset, onlyReal]);

  useEffect(() => {
    void load();
  }, [load]);

  if (!getToken()) {
    // Not an error, and worth saying so. The access token is held in memory
    // only and never in localStorage, so a hard refresh or a typed URL
    // genuinely has no session — see lib/api.ts for why that trade was made.
    // Saying "sign in" without the reason makes a deliberate security property
    // look like a broken page.
    return (
      <main>
        <h1>Model QA</h1>
        <div className="panel">
          <p style={{ margin: 0 }}>No session in this tab.</p>
          <p className="hint" style={{ margin: "8px 0 0" }}>
            The access token is kept in memory and never in <code>localStorage</code>,
            so opening this URL directly — or refreshing — starts signed out. That is
            deliberate: anything in <code>localStorage</code> is readable by any script
            on the page, which turns one XSS into stolen credentials.
          </p>
          <p className="hint" style={{ margin: "8px 0 0" }}>
            <Link href="/">Go to the wardrobe</Link>, sign in, then use the{" "}
            <strong>Model QA</strong> link at the top — that navigates without a page
            load, so the session survives.
          </p>
        </div>
      </main>
    );
  }

  return (
    <main>
      <h1>Model QA</h1>
      <p className="hint">
        What each model actually produced, next to the photo it came from.
      </p>

      {error && <div className="err">{error}</div>}

      {/* Driven by what ACTUALLY tagged (from `model_calls`), not by this
          service's own config. The two drifted once — the API was missing
          VLM_MODEL while the worker had it — and this banner told people their
          real Gemini tags were a stand-in. A warning that is wrong in that
          direction teaches users to distrust correct output. */}
      {page?.tagging_is_mock === true && (
        <div className="panel warn">
          <strong>Tagging is not running a real model.</strong>
          <p className="hint" style={{ margin: "6px 0 0" }}>
            <code>{page.tagging_model}</code> is a deterministic stand-in that answers{" "}
            <code>kurta</code> for everything. Segmentation, cutout, colour, moderation,
            embeddings and dedupe below are all real work on your photos — only the
            category-ish fields are placeholders. Set <code>GEMINI_API_KEY</code> and{" "}
            <code>VLM_MODEL=vlm-tagger</code> in <code>.env</code> for real tags.
          </p>
        </div>
      )}

      {/* Nothing tagged yet is NOT the same as "tags are real", so it gets its
          own message rather than silently showing no banner. */}
      {page?.tagging_is_mock === null && (
        <div className="panel">
          <strong>No garments have been tagged yet.</strong>
          <p className="hint" style={{ margin: "6px 0 0" }}>
            Tagging is configured to use <code>{page.tagging_model_configured}</code>. Upload a
            photo to see real tags here.
          </p>
        </div>
      )}

      {/* A disagreement between what ran and what is configured is worth
          seeing rather than resolving silently in favour of either.

          IT PERSISTS UNTIL SOMETHING RE-TAGS, AND THAT IS CORRECT. Changing
          VLM_MODEL does not change tags that already exist, so the warning is
          a fact about history, not a setting to dismiss. The old copy read
          "Tags below were produced by the first", which was a guess: this page
          routinely mixes models, and on a real account it was five Gemini,
          three MOCK and one unrecorded. Claiming one model for all of them hid
          the mock rows behind a real model's name. The distribution is now
          read from `model_calls` per row. */}
      {page?.tagging_config_disagrees && (
        <div className="panel warn">
          <strong>Config and reality disagree.</strong>
          <p className="hint" style={{ margin: "6px 0 0" }}>
            The last tag call on this account used <code>{page.tagging_model}</code>, but
            this service is now configured for{" "}
            <code>{page.tagging_model_configured}</code>. Existing tags are not rewritten
            by a config change, so this stays until something is tagged again.
          </p>
          {page.tagging_models_on_page.length > 0 && (
            <p className="hint" style={{ margin: "6px 0 0" }}>
              What actually tagged the {page.tagging_mixed_on_page ? "rows" : "rows"} below:{" "}
              {page.tagging_models_on_page.map((m, i) => (
                <span key={m.model}>
                  {i > 0 ? ", " : ""}
                  <code>{m.model}</code> ×{m.garments}
                </span>
              ))}
              .
            </p>
          )}
        </div>
      )}

      <div className="searchrow" style={{ marginBottom: 14 }}>
        <label className="chk">
          <input
            type="checkbox"
            checked={onlyReal}
            onChange={(e) => {
              setOffset(0);
              setOnlyReal(e.target.checked);
            }}
          />
          Only garments with real model output
        </label>
        {page && (
          <span className="muted">
            {page.total} garment{page.total === 1 ? "" : "s"}
          </span>
        )}
      </div>

      {page && page.items.length === 0 && (
        <div className="empty">
          {onlyReal
            ? "No garments here have real model output yet. Upload a photo, or turn the filter off to see the seeded and mock-tagged ones."
            : "Nothing to show. Upload a photo on the wardrobe page."}
        </div>
      )}

      <div className="evalgrid">
        {page?.items.map((it) => (
          <div className={`panel evalcard ${it.tag_is_real ? "" : "notreal"}`} key={it.id}>
            <div className="evalthumb">
              {(showOriginal[it.id] ? it.original_url : it.cutout_url) ? (
                // eslint-disable-next-line @next/next/no-img-element
                <img
                  src={(showOriginal[it.id] ? it.original_url : it.cutout_url) ?? ""}
                  alt="garment"
                />
              ) : (
                <span className="muted">no image</span>
              )}
              {it.original_url && it.cutout_url && (
                <button
                  className="link"
                  onClick={() =>
                    setShowOriginal((p) => ({ ...p, [it.id]: !p[it.id] }))
                  }
                >
                  {showOriginal[it.id] ? "show cutout" : "show original"}
                </button>
              )}
            </div>

            <table className="evaltable">
              <tbody>
                {it.fields.map((f) => (
                  <tr key={f.field} className={f.below_threshold ? "lowrow" : ""}>
                    <th>{f.field.replace(/_/g, " ")}</th>
                    <td>{f.value === null ? <span className="muted">—</span> : String(f.value)}</td>
                    <td className="conf">
                      <Confidence f={f} />
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>

            <div className="prov">
              <div className={it.tag_is_real ? "" : "provwarn"}>
                tags: {it.tag_source}
              </div>
              {it.tag_degraded && (
                <div className="provwarn">
                  tagging DEGRADED{it.tag_reason ? ` — ${it.tag_reason}` : ""}
                </div>
              )}
              <div>
                embedding: {it.has_embedding ? (it.embedding_version ?? "yes") : "none"}
              </div>
              {typeof it.moderation?.score === "number" && (
                <div>nsfw score: {(it.moderation.score as number).toFixed(4)}</div>
              )}
              {it.phash && <div>phash: {it.phash}</div>}
              {it.duplicate_of && (
                <div className="provwarn">flagged as a possible duplicate</div>
              )}
              <div className="muted">
                {it.state}
                {it.needs_review ? " · needs review" : ""}
              </div>
            </div>
          </div>
        ))}
      </div>

      {page && page.total > PAGE && (
        <div className="searchrow" style={{ marginTop: 16 }}>
          <button
            className="link"
            disabled={offset === 0}
            onClick={() => setOffset(Math.max(0, offset - PAGE))}
          >
            ← previous
          </button>
          <span className="muted">
            {offset + 1}–{Math.min(offset + PAGE, page.total)} of {page.total}
          </span>
          <button
            className="link"
            disabled={offset + PAGE >= page.total}
            onClick={() => setOffset(offset + PAGE)}
          >
            next →
          </button>
        </div>
      )}
    </main>
  );
}
